-- ── §1–§4 Reference tables ────────────────────────────────────────────────────────────────────────────
CREATE TABLE public.portion_categories (
  category          text PRIMARY KEY CHECK (category ~ '^[a-z][a-z_]*$'),
  parent            text REFERENCES public.portion_categories(category) ON DELETE RESTRICT,
  density_g_per_ml  numeric CHECK (density_g_per_ml > 0 AND density_g_per_ml <= 2),
  s_ratio           numeric NOT NULL CHECK (s_ratio > 0 AND s_ratio <= 1),
  l_ratio           numeric NOT NULL CHECK (l_ratio >= 1 AND l_ratio <= 3),
  serving_unit      text CHECK (serving_unit IN ('piece','slice','katori','bowl','plate','cup','glass','mug','cutting','tbsp','tsp','spoon','handful','scoop','splash','serving','can','bottle','packet','pint','peg','shot')),   -- what "no amount" means (katori for dal)
  inherit_vessels   boolean NOT NULL DEFAULT true,   -- false (condiment): the generic katori/bowl/cup/glass/mug/plate rows never apply
  kcal100_min       numeric CHECK (kcal100_min >= 0),   -- Phase 7 AI-estimate clamp for this category only (not inherited); NULL = none
  kcal100_max       numeric CHECK (kcal100_max > 0),
  note              text NOT NULL CHECK (btrim(note) <> ''),
  CHECK ((parent IS NULL) = (category = 'generic')),
  CHECK (kcal100_min IS NULL OR kcal100_max IS NULL OR kcal100_min < kcal100_max)
);
CREATE TABLE public.portion_category_words (
  word      text PRIMARY KEY CHECK (word <> '' AND word = btrim(regexp_replace(regexp_replace(lower(word), '[^[:alnum:][:space:]]', ' ', 'g'), '\s+', ' ', 'g'))),
  category  text NOT NULL REFERENCES public.portion_categories(category) ON DELETE RESTRICT,
  priority  int  NOT NULL DEFAULT 50,
  head_only boolean NOT NULL DEFAULT false   -- an ingredient word (butter, milk, egg): names the food only as the phrase's LAST word
);
CREATE TABLE public.portion_category_map (
  food_item_id uuid PRIMARY KEY REFERENCES public.food_items(id) ON DELETE RESTRICT,
  category     text NOT NULL REFERENCES public.portion_categories(category) ON DELETE RESTRICT,
  note         text NOT NULL CHECK (btrim(note) <> '')
);
CREATE TABLE public.portion_units (
  id               uuid PRIMARY KEY,                               -- UUIDv5 of the natural key (scripts/portions/lib.ts)
  food_item_id     uuid REFERENCES public.food_items(id) ON DELETE RESTRICT,
  fdc_id           bigint CHECK (fdc_id > 0),
  category         text REFERENCES public.portion_categories(category) ON DELETE RESTRICT,
  unit             text NOT NULL CHECK (unit IN ('piece','slice','katori','bowl','plate','cup','glass','mug','cutting','tbsp','tsp','spoon','handful','scoop','splash','serving','can','bottle','packet','pint','peg','shot','ml')),   -- 'ml' = a density-only row (USDA "1 fl oz")
  size             text NOT NULL DEFAULT 'M' CHECK (size IN ('S','M','L')),
  grams            numeric CHECK (grams > 0 AND grams <= 10000),
  ml               numeric CHECK (ml > 0 AND ml <= 10000),
  context          text CHECK (context IN ('home','restaurant')),   -- NULL = any
  region           text CHECK (region IN ('IN','US')),              -- NULL = neutral
  is_default       boolean NOT NULL DEFAULT false,   -- the serving used when no amount is given
  is_unit_default  boolean NOT NULL DEFAULT false,   -- the size meant when no size word is given
  source           text NOT NULL CHECK (source IN ('founder','weighed','research','legacy_hint','mapping','food_items_portions','usda_foundation','usda_sr','usda_fndds')),
  grade            text NOT NULL CHECK (grade IN ('F','A','B','C','U','H')),
  confidence       numeric NOT NULL CHECK (confidence > 0 AND confidence <= 1),
  source_ref       text NOT NULL CHECK (btrim(source_ref) <> ''),
  source_text      text,
  approved_by      text,
  status           text NOT NULL DEFAULT 'active' CHECK (status IN ('active','proposed','retired')),
  evidence         text NOT NULL CHECK (btrim(evidence) <> ''),
  created_at       timestamptz NOT NULL DEFAULT now(),
  CHECK (num_nonnulls(food_item_id, fdc_id, category) = 1),
  CHECK (grams IS NOT NULL OR ml IS NOT NULL),
  CHECK (unit <> 'ml' OR (grams IS NOT NULL AND ml IS NOT NULL)),
  CHECK (status <> 'active' OR approved_by IS NOT NULL OR source IN ('food_items_portions','usda_foundation','usda_sr','usda_fndds'))
);
CREATE UNIQUE INDEX portion_units_active_key ON public.portion_units
  (coalesce(food_item_id::text, ''), coalesce(fdc_id, 0), coalesce(category, ''), unit, size, coalesce(context, ''), coalesce(region, ''))
  WHERE status = 'active';
CREATE UNIQUE INDEX portion_units_default_key ON public.portion_units
  (coalesce(food_item_id::text, ''), coalesce(fdc_id, 0), coalesce(category, ''), coalesce(region, ''), coalesce(context, ''))
  WHERE status = 'active' AND is_default;
CREATE UNIQUE INDEX portion_units_unit_default_key ON public.portion_units
  (coalesce(food_item_id::text, ''), coalesce(fdc_id, 0), coalesce(category, ''), unit, coalesce(region, ''), coalesce(context, ''))
  WHERE status = 'active' AND is_unit_default;
CREATE INDEX portion_units_food_idx ON public.portion_units (food_item_id) WHERE food_item_id IS NOT NULL;
CREATE INDEX portion_units_fdc_idx  ON public.portion_units (fdc_id) WHERE fdc_id IS NOT NULL;
CREATE INDEX portion_units_category_idx ON public.portion_units (category) WHERE category IS NOT NULL;
COMMENT ON TABLE public.portion_units IS
  'Portion grams by unit (v1.2 Phase 5, migration 054). Keyed by one of food_item_id / fdc_id / category; read by the portion engine '
   'only when PORTION_MODE is not legacy. Written by reviewed migrations only. proposed rows are served under eval_only only.';

-- ── §4b Personal calibration (founder 2026-11-13, spec k16) ─────────────────────────────────────────────
-- One active row per (user, scope, unit, size). grams, ml or as_size ("my katori is small": an unsized katori
-- means S). Applied right after memory and above every default (portion_source user_calibration). Undo =
-- revoked_at; a replaced row is revoked too, so the history of what the user told us stays readable.
CREATE TABLE IF NOT EXISTS public.user_portion_calibrations (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id         uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  scope           text NOT NULL CHECK (scope IN ('any','category','food')),
  category        text,
  food_item_id    uuid REFERENCES public.food_items(id) ON DELETE CASCADE,
  unit            text NOT NULL CHECK (unit IN ('piece','slice','katori','bowl','plate','cup','glass','mug','cutting','tbsp','tsp','spoon','handful','scoop','splash','serving','can','bottle','packet','pint','peg','shot')),
  size            text NOT NULL DEFAULT 'M' CHECK (size IN ('S','M','L')),
  grams           numeric CHECK (grams > 0 AND grams <= 10000),
  ml              numeric CHECK (ml > 0 AND ml <= 10000),
  as_size         text CHECK (as_size IN ('S','M','L')),
  origin          text NOT NULL CHECK (origin IN ('statement','edit','edit_confirmed','chip','follow_up')),   -- edit = one edit, served at low confidence until a second edit confirms it
  source_text     text CHECK (source_text IS NULL OR length(source_text) <= 200),   -- the user's own words, their own row
  created_at      timestamptz NOT NULL DEFAULT now(),
  revoked_at      timestamptz,
  revoked_reason  text CHECK (revoked_reason IN ('replaced','user_undo')),
  CHECK (num_nonnulls(grams, ml, as_size) = 1),
  CHECK (as_size IS NULL OR size = 'M'),
  CHECK ((revoked_at IS NULL) = (revoked_reason IS NULL)),
  CHECK ((scope = 'any' AND category IS NULL AND food_item_id IS NULL)
      OR (scope = 'category' AND category IS NOT NULL AND food_item_id IS NULL)
      OR (scope = 'food' AND food_item_id IS NOT NULL AND category IS NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS user_portion_calibrations_active_key ON public.user_portion_calibrations
  (user_id, scope, coalesce(category, ''), coalesce(food_item_id::text, ''), unit, size) WHERE revoked_at IS NULL;
CREATE INDEX IF NOT EXISTS user_portion_calibrations_user_idx ON public.user_portion_calibrations (user_id) WHERE revoked_at IS NULL;
CREATE INDEX IF NOT EXISTS user_portion_calibrations_food_idx ON public.user_portion_calibrations (food_item_id) WHERE food_item_id IS NOT NULL;
COMMENT ON TABLE public.user_portion_calibrations IS
  'A user''s own unit sizes (054, spec k16). Per user, never shared: the Edge Functions (service_role) filter by user_id and are the '
   'only writers, through set_portion_calibration / revoke_portion_calibrations. Users read their own rows (RLS).';

CREATE OR REPLACE FUNCTION public.set_portion_calibration(
  p_user_id uuid, p_scope text, p_category text, p_food_item_id uuid, p_unit text, p_size text,
  p_grams numeric, p_ml numeric, p_as_size text, p_origin text, p_source_text text)
RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $f$
DECLARE
  v_id uuid;
BEGIN
  -- one writer per user at a time: the revoke + insert below must not interleave with a twin call
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('user_portion_calibrations:' || p_user_id::text, 0));
  UPDATE public.user_portion_calibrations SET revoked_at = pg_catalog.now(), revoked_reason = 'replaced'
   WHERE user_id = p_user_id AND revoked_at IS NULL AND scope = p_scope
     AND category IS NOT DISTINCT FROM p_category AND food_item_id IS NOT DISTINCT FROM p_food_item_id
     AND unit = p_unit AND size = coalesce(p_size, 'M');
  INSERT INTO public.user_portion_calibrations
    (user_id, scope, category, food_item_id, unit, size, grams, ml, as_size, origin, source_text)
  VALUES (p_user_id, p_scope, p_category, p_food_item_id, p_unit, coalesce(p_size, 'M'), p_grams, p_ml, p_as_size, p_origin,
          pg_catalog.left(p_source_text, 200))
  RETURNING id INTO v_id;
  RETURN v_id;
END
$f$;
-- p_scope + p_category / p_food_item_id narrow an undo to one category or food ("forget my chai cup size"); without them
-- a unit is undone in every scope ("forget my cup size").
CREATE OR REPLACE FUNCTION public.revoke_portion_calibrations(
  p_user_id uuid, p_id uuid DEFAULT NULL, p_unit text DEFAULT NULL, p_all boolean DEFAULT false,
  p_scope text DEFAULT NULL, p_category text DEFAULT NULL, p_food_item_id uuid DEFAULT NULL)
RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $f$
DECLARE
  v_n integer;
BEGIN
  IF p_id IS NULL AND p_unit IS NULL AND NOT coalesce(p_all, false) THEN
    RAISE EXCEPTION 'revoke_portion_calibrations: give an id, a unit, or p_all => true';
  END IF;
  IF (p_scope = 'category' AND (p_category IS NULL OR p_food_item_id IS NOT NULL))
     OR (p_scope = 'food' AND (p_food_item_id IS NULL OR p_category IS NOT NULL))
     OR (p_scope IS NOT NULL AND p_scope NOT IN ('category', 'food'))
     OR (p_scope IS NULL AND (p_category IS NOT NULL OR p_food_item_id IS NOT NULL)) THEN
    RAISE EXCEPTION 'revoke_portion_calibrations: p_scope category needs p_category, food needs p_food_item_id';
  END IF;
  UPDATE public.user_portion_calibrations SET revoked_at = pg_catalog.now(), revoked_reason = 'user_undo'
   WHERE user_id = p_user_id AND revoked_at IS NULL
     AND (p_id IS NULL OR id = p_id) AND (p_unit IS NULL OR unit = p_unit)
     AND (p_scope IS NULL OR scope = p_scope) AND (p_category IS NULL OR category = p_category)
     AND (p_food_item_id IS NULL OR food_item_id = p_food_item_id);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END
$f$;

-- ── §5 Memory portions validator (user_food_memory.portions; TS twin: _shared/portionMemory.ts) ───────────
-- An array of at most 24 {unit, size, grams, origin, at}; (unit, size) unique. Every cast is guarded by a CASE,
-- so a malformed value is false, never an error.
CREATE OR REPLACE FUNCTION public.portion_memory_ok(p jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path = '' AS $f$
  SELECT CASE
    WHEN p IS NULL THEN true
    WHEN pg_catalog.jsonb_typeof(p) <> 'array' THEN false
    WHEN pg_catalog.jsonb_array_length(p) > 24 THEN false
    ELSE coalesce((
      SELECT pg_catalog.bool_and(CASE
        WHEN pg_catalog.jsonb_typeof(e) <> 'object' THEN false
        WHEN EXISTS (SELECT 1 FROM pg_catalog.jsonb_object_keys(e) k WHERE k NOT IN ('unit','size','grams','origin','at')) THEN false
        WHEN pg_catalog.jsonb_typeof(e->'unit') IS DISTINCT FROM 'string' OR (e->>'unit') NOT IN ('piece','slice','katori','bowl','plate','cup','glass','mug','cutting','tbsp','tsp','spoon','handful','scoop','splash','serving','can','bottle','packet','pint','peg','shot') THEN false
        WHEN pg_catalog.jsonb_typeof(e->'size') IS DISTINCT FROM 'string' OR (e->>'size') NOT IN ('S','M','L') THEN false
        WHEN pg_catalog.jsonb_typeof(e->'grams') IS DISTINCT FROM 'number' THEN false
        WHEN NOT ((e->>'grams')::numeric > 0 AND (e->>'grams')::numeric <= 10000) THEN false
        WHEN pg_catalog.jsonb_typeof(e->'origin') IS DISTINCT FROM 'string' OR (e->>'origin') NOT IN ('correction','calibration','manual','label') THEN false
        WHEN pg_catalog.jsonb_typeof(e->'at') IS DISTINCT FROM 'string' THEN false
        WHEN (e->>'at') !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN false
        WHEN pg_catalog.substr(e->>'at', 1, 4) = '0000' THEN false
        ELSE pg_catalog.substr(e->>'at', 9, 2)::int <= pg_catalog.date_part('day',
               pg_catalog.make_date(pg_catalog.substr(e->>'at', 1, 4)::int, pg_catalog.substr(e->>'at', 6, 2)::int, 1)
               + interval '1 month' - interval '1 day')
      END)
      FROM pg_catalog.jsonb_array_elements(p) e), true)
      AND (SELECT count(*) = count(DISTINCT (e->>'unit') || '|' || (e->>'size')) FROM pg_catalog.jsonb_array_elements(p) e)
  END
$f$;
ALTER TABLE public.user_food_memory DROP CONSTRAINT IF EXISTS user_food_memory_portions_ok;
ALTER TABLE public.user_food_memory ADD CONSTRAINT user_food_memory_portions_ok
  CHECK (portions IS NULL OR public.portion_memory_ok(portions)) NOT VALID;
ALTER TABLE public.user_food_memory VALIDATE CONSTRAINT user_food_memory_portions_ok;

-- ── §6 food_entries: what the portion was (nullable; adding them changes metadata only) ─────────────────────
ALTER TABLE public.food_entries
  ADD COLUMN IF NOT EXISTS portion_unit       text CHECK (portion_unit IN ('piece','slice','katori','bowl','plate','cup','glass','mug','cutting','tbsp','tsp','spoon','handful','scoop','splash','serving','can','bottle','packet','pint','peg','shot','g','ml')),
  ADD COLUMN IF NOT EXISTS portion_size       text CHECK (portion_size IN ('S','M','L')),
  ADD COLUMN IF NOT EXISTS portion_count      numeric CHECK (portion_count > 0 AND portion_count <= 100),
  ADD COLUMN IF NOT EXISTS portion_source     text CHECK (portion_source IN ('stated','memory','user_calibration','food','category','volume','serving_default','ai','label','edit_rescale','rule','legacy')),
  ADD COLUMN IF NOT EXISTS portion_confidence numeric CHECK (portion_confidence >= 0 AND portion_confidence <= 1);

-- ── §7 Index: the fdc_id map (none today) ───────────────────────────────────────────────────────────────
CREATE INDEX IF NOT EXISTS food_items_fdc_id_idx ON public.food_items (fdc_id) WHERE fdc_id IS NOT NULL;

-- ── §8 Privileges (052 pattern): live default privileges hand anon/authenticated arwdDxtm on new tables ──────
DO $priv$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['portion_categories','portion_category_words','portion_category_map','portion_units'] LOOP
    EXECUTE pg_catalog.format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);                       -- no policies
    EXECUTE pg_catalog.format('REVOKE ALL ON public.%I FROM PUBLIC, anon, authenticated, service_role', t);
    EXECUTE pg_catalog.format('GRANT SELECT ON public.%I TO service_role', t);                              -- writes: migrations only
  END LOOP;
END $priv$;
ALTER TABLE public.user_portion_calibrations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.user_portion_calibrations FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON public.user_portion_calibrations TO authenticated;                 -- own rows only (policy below)
GRANT SELECT, INSERT, UPDATE ON public.user_portion_calibrations TO service_role;  -- no DELETE: undo is revoked_at
DROP POLICY IF EXISTS "Users read own portion calibrations" ON public.user_portion_calibrations;
CREATE POLICY "Users read own portion calibrations" ON public.user_portion_calibrations
  FOR SELECT TO authenticated USING ((SELECT auth.uid()) = user_id);
REVOKE ALL ON FUNCTION public.portion_memory_ok(jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.portion_memory_ok(jsonb) TO service_role;
REVOKE ALL ON FUNCTION public.set_portion_calibration(uuid, text, text, uuid, text, text, numeric, numeric, text, text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.set_portion_calibration(uuid, text, text, uuid, text, text, numeric, numeric, text, text, text) TO service_role;
REVOKE ALL ON FUNCTION public.revoke_portion_calibrations(uuid, uuid, text, boolean, text, text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.revoke_portion_calibrations(uuid, uuid, text, boolean, text, text, uuid) TO service_role;

