  (2710472, '1 cup (8 fl oz)', 240),
  (2710472, '1 fl oz', 30),
  (2710472, '1 large', 600),
  (2710472, '1 medium', 480),
  (2710472, '1 small', 360);

DO $seed$
BEGIN
  IF (SELECT go FROM _state054) THEN
    INSERT INTO public.portion_category_map (food_item_id, category, note) SELECT food_item_id, category, note FROM _map054;
    INSERT INTO public.portion_units (id, food_item_id, fdc_id, category, unit, size, grams, ml, context, region, is_default,
        is_unit_default, source, grade, confidence, source_ref, source_text, approved_by, status, evidence)
      SELECT id, food_item_id, fdc_id, category, unit, size, grams, ml, context, region, is_default, is_unit_default, source,
             grade, confidence, source_ref, source_text, approved_by, status, evidence FROM _pu054;
  ELSE
    INSERT INTO public.portion_units (id, food_item_id, fdc_id, category, unit, size, grams, ml, context, region, is_default,
        is_unit_default, source, grade, confidence, source_ref, source_text, approved_by, status, evidence)
      SELECT id, food_item_id, fdc_id, category, unit, size, grams, ml, context, region, is_default, is_unit_default, source,
             grade, confidence, source_ref, source_text, approved_by, status, evidence FROM _pu054 WHERE food_item_id IS NULL;
    RAISE NOTICE '054: no 053 production rows here (migrations-only replay): founder rows and the category map skipped';
  END IF;
END
$seed$;
-- user_portion_calibrations.category -> portion_categories, added once the categories exist (here, after the seed):
-- on a re-push after the down script kept a non-empty calibrations table, its existing rows are validated too.
DO $calfk$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint WHERE conname = 'user_portion_calibrations_category_fkey'
                   AND conrelid = 'public.user_portion_calibrations'::regclass) THEN
    ALTER TABLE public.user_portion_calibrations ADD CONSTRAINT user_portion_calibrations_category_fkey
      FOREIGN KEY (category) REFERENCES public.portion_categories(category) ON DELETE RESTRICT NOT VALID;
    ALTER TABLE public.user_portion_calibrations VALIDATE CONSTRAINT user_portion_calibrations_category_fkey;
  END IF;
END $calfk$;

-- ── §10 Compare-and-swap with 053 (and with the fold-in snapshot) ──────────────────────────────────────────
DO $cas$
DECLARE
  v_bad text;
BEGIN
  IF NOT (SELECT go FROM _state054) THEN RETURN; END IF;
  -- every founder row: its food_items row is verified and still carries {description: source_text, gramWeight: grams}
  SELECT string_agg(pg_catalog.left(p.food_item_id::text, 8) || ' ' || p.unit || ' ' || p.source_text || ' = ' || p.grams
                    || ' (' || coalesce(fi.status, 'missing') || ')', '; ' ORDER BY p.food_item_id, p.unit) INTO v_bad
    FROM _pu054 p LEFT JOIN public.food_items fi ON fi.id = p.food_item_id
   WHERE p.source = 'founder'
     AND (fi.id IS NULL OR fi.status <> 'verified' OR fi.portions IS NULL OR pg_catalog.jsonb_typeof(fi.portions) <> 'array'
          OR NOT EXISTS (SELECT 1 FROM pg_catalog.jsonb_array_elements(fi.portions) e
                          WHERE e->>'description' = p.source_text AND pg_catalog.jsonb_typeof(e->'gramWeight') = 'number'
                            AND (e->>'gramWeight')::numeric = p.grams));
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '054: founder rows disagree with food_items (053 regenerated? regenerate 054): %', v_bad;
  END IF;
  -- every fold-in source entry is still on a verified row with that fdc_id
  SELECT string_agg(f.fdc_id || ' ' || f.description || ' = ' || f.grams, '; ' ORDER BY f.fdc_id, f.description) INTO v_bad
    FROM _fold054 f
   WHERE NOT EXISTS (SELECT 1 FROM public.food_items fi CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
                       CASE WHEN pg_catalog.jsonb_typeof(fi.portions) = 'array' THEN fi.portions ELSE '[]'::jsonb END) e
                      WHERE fi.fdc_id = f.fdc_id AND fi.status = 'verified' AND e->>'description' = f.description
                        AND pg_catalog.jsonb_typeof(e->'gramWeight') = 'number' AND (e->>'gramWeight')::numeric = f.grams);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION '054: fold-in snapshot entries no longer on a verified row (re-take the snapshot and regenerate): %', v_bad;
  END IF;
  -- the category map points at verified rows
  SELECT string_agg(pg_catalog.left(m.food_item_id::text, 8), ', ') INTO v_bad
    FROM _map054 m LEFT JOIN public.food_items fi ON fi.id = m.food_item_id WHERE fi.id IS NULL OR fi.status <> 'verified';
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '054: category map rows not verified: %', v_bad; END IF;
END
$cas$;

-- ── §11 Self-checks (any failure rolls back everything above) ───────────────────────────────────────────
DO $chk$
DECLARE
  v_bad text; v_n bigint; v_go boolean := (SELECT go FROM _state054);
BEGIN
  -- 1. the tree: every category reaches generic, no cycle; every serving_unit has an active row in its chain
  WITH RECURSIVE up(start, cat, depth) AS (
    SELECT category, category, 0 FROM public.portion_categories
    UNION ALL
    SELECT up.start, pc.parent, up.depth + 1 FROM up JOIN public.portion_categories pc ON pc.category = up.cat
     WHERE pc.parent IS NOT NULL AND up.depth < 20)
  SELECT string_agg(c.category, ', ') INTO v_bad FROM public.portion_categories c
   WHERE NOT EXISTS (SELECT 1 FROM up WHERE up.start = c.category AND up.cat = 'generic');
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '054: categories that do not reach generic: %', v_bad; END IF;
  WITH RECURSIVE up(start, cat, depth) AS (
    SELECT category, category, 0 FROM public.portion_categories
    UNION ALL
    SELECT up.start, pc.parent, up.depth + 1 FROM up JOIN public.portion_categories pc ON pc.category = up.cat
     WHERE pc.parent IS NOT NULL AND up.depth < 20)
  SELECT string_agg(c.category || ':' || c.serving_unit, ', ') INTO v_bad FROM public.portion_categories c
   WHERE c.serving_unit IS NOT NULL AND NOT EXISTS (
     SELECT 1 FROM up JOIN public.portion_units pu ON pu.category = up.cat AND pu.unit = c.serving_unit AND pu.status = 'active'
      WHERE up.start = c.category);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '054: serving units with no active row in the chain: %', v_bad; END IF;
  -- 2. row counts per source/status = the emitter manifest
  SELECT string_agg(m.k || ' got ' || coalesce(g.n, 0) || ' expected ' || CASE WHEN v_go THEN m.n_prod ELSE m.n_replay END, '; ') INTO v_bad
    FROM (VALUES
      ('food_items_portions/active', 146, 146),
      ('founder/active', 98, 0),
      ('legacy_hint/active', 45, 45),
      ('legacy_hint/retired', 8, 8),
      ('mapping/proposed', 7, 7),
      ('research/active', 152, 150)
    ) AS m(k, n_prod, n_replay)
    LEFT JOIN (SELECT source || '/' || status AS k, count(*) AS n FROM public.portion_units GROUP BY 1) g ON g.k = m.k
   WHERE coalesce(g.n, 0) <> CASE WHEN v_go THEN m.n_prod ELSE m.n_replay END;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '054: row counts differ from the manifest: %', v_bad; END IF;
  SELECT count(*) INTO v_n FROM public.portion_units;
  IF v_n <> (CASE WHEN v_go THEN 456 ELSE 356 END) THEN   -- parenthesised: plpgsql's IF reads up to the first THEN
    RAISE EXCEPTION '054: % portion rows, manifest says otherwise', v_n;
  END IF;
  IF v_go AND (SELECT count(*) FROM public.portion_category_map) <> 54 THEN
    RAISE EXCEPTION '054: category map has % rows, expected 54', (SELECT count(*) FROM public.portion_category_map);
  END IF;
  -- 3. no active generic piece / slice / packet / can / bottle row (container sizes are product facts)
  SELECT string_agg(unit, ', ') INTO v_bad FROM public.portion_units
   WHERE category = 'generic' AND status = 'active' AND unit IN ('piece','slice','packet','can','bottle');
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION '054: generic container/piece rows: %', v_bad; END IF;
  -- 4. every active research / legacy_hint / mapping row has approved_by (the CHECK says so too)
  SELECT count(*) INTO v_n FROM public.portion_units WHERE status = 'active' AND source IN ('research','legacy_hint','mapping') AND approved_by IS NULL;
  IF v_n > 0 THEN RAISE EXCEPTION '054: % active research/hint/mapping rows without approved_by', v_n; END IF;
  -- 5. privileges: the reference tables are server-side only; calibrations readable by their owner only
  IF has_table_privilege('anon', 'public.portion_units', 'SELECT') OR has_table_privilege('authenticated', 'public.portion_units', 'SELECT')
     OR has_table_privilege('anon', 'public.portion_categories', 'SELECT') OR has_table_privilege('authenticated', 'public.portion_categories', 'SELECT')
     OR has_table_privilege('anon', 'public.portion_category_words', 'SELECT') OR has_table_privilege('authenticated', 'public.portion_category_words', 'SELECT')
     OR has_table_privilege('anon', 'public.portion_category_map', 'SELECT') OR has_table_privilege('authenticated', 'public.portion_category_map', 'SELECT')
     OR has_table_privilege('service_role', 'public.portion_units', 'INSERT')
     OR NOT has_table_privilege('service_role', 'public.portion_units', 'SELECT')
     OR has_table_privilege('anon', 'public.user_portion_calibrations', 'SELECT')
     OR has_table_privilege('authenticated', 'public.user_portion_calibrations', 'INSERT')
     OR has_table_privilege('authenticated', 'public.user_portion_calibrations', 'UPDATE')
     OR has_table_privilege('service_role', 'public.user_portion_calibrations', 'DELETE')
     OR NOT has_table_privilege('service_role', 'public.user_portion_calibrations', 'INSERT')
     OR has_function_privilege('anon', 'public.set_portion_calibration(uuid, text, text, uuid, text, text, numeric, numeric, text, text, text)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.set_portion_calibration(uuid, text, text, uuid, text, text, numeric, numeric, text, text, text)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.revoke_portion_calibrations(uuid, uuid, text, boolean, text, text, uuid)', 'EXECUTE')
     OR has_function_privilege('anon', 'public.portion_memory_ok(jsonb)', 'EXECUTE')
     OR NOT (SELECT relrowsecurity FROM pg_catalog.pg_class WHERE oid = 'public.user_portion_calibrations'::regclass) THEN
    RAISE EXCEPTION '054: privileges on the portion tables or functions are wrong';
  END IF;
  -- 6. history untouched (the tables were locked throughout)
  IF (SELECT ROW(e, d, s) FROM _fp054) IS DISTINCT FROM ROW(
    (SELECT count(*) || ':' || md5(coalesce(string_agg(concat_ws(':', id, food_item_id, quantity_g, calories, protein_g, carbs_g, fat_g, fiber_g), ',' ORDER BY id), '')) FROM public.food_entries),
    (SELECT count(*) || ':' || md5(coalesce(string_agg(concat_ws(':', id, total_calories, total_protein_g, total_carbs_g, total_fat_g), ',' ORDER BY id), '')) FROM public.daily_summaries),
    (SELECT count(*) || ':' || md5(coalesce(string_agg(id || entries::text, ',' ORDER BY id), '')) FROM public.saved_entries)) THEN
    RAISE EXCEPTION '054: food_entries / daily_summaries / saved_entries changed';
  END IF;
  -- 7. every verified food_items row holds a key (055 imports key-less verified rows and relies on this today)
  SELECT count(*) INTO v_n FROM public.food_items WHERE status = 'verified' AND normalized_name IS NULL;
  IF v_n > 0 THEN RAISE EXCEPTION '054: % verified rows without a key', v_n; END IF;
  -- 8. the memory validator agrees with its own fixtures (full agreement with the TS twin: memoryPortions.test.ts)
  IF NOT public.portion_memory_ok('[{"unit":"katori","size":"M","grams":150,"origin":"correction","at":"2026-11-13"}]'::jsonb)
     OR public.portion_memory_ok('[{"unit":"ml","size":"M","grams":150,"origin":"correction","at":"2026-11-13"}]'::jsonb)
     OR public.portion_memory_ok('[{"unit":"cup","size":"M","grams":"150","origin":"manual","at":"2026-11-13"}]'::jsonb)
     OR public.portion_memory_ok('[{"unit":"cup","size":"M","grams":150,"origin":"manual","at":"2026-02-30"}]'::jsonb)
     OR public.portion_memory_ok('[{"unit":"cup","size":"M","grams":150,"origin":"manual","at":"2026-11-13"},{"unit":"cup","size":"M","grams":120,"origin":"label","at":"2026-11-13"}]'::jsonb)
     OR NOT public.portion_memory_ok(NULL) THEN
    RAISE EXCEPTION '054: portion_memory_ok fixtures disagree';
  END IF;
  -- 9. no memory row fails the validator (the CHECK was validated above; belt and braces)
  SELECT count(*) INTO v_n FROM public.user_food_memory WHERE portions IS NOT NULL AND NOT public.portion_memory_ok(portions);
  IF v_n > 0 THEN RAISE EXCEPTION '054: % memory rows fail portion_memory_ok', v_n; END IF;
  -- 10. spot checks the engine relies on (production only)
  IF v_go THEN
    IF (SELECT grams FROM public.portion_units WHERE food_item_id = '8cbd7524-bc18-5e4c-862b-cd6d61ee08b6' AND unit = 'katori' AND status = 'active') IS DISTINCT FROM 150
       OR (SELECT grams FROM public.portion_units WHERE food_item_id = 'e21a4369-e513-534a-8968-4e4240e871d0' AND unit = 'cup' AND status = 'active') IS DISTINCT FROM 128
       OR (SELECT grams FROM public.portion_units WHERE food_item_id = '2f9486f1-e89e-563d-9dba-dc4b9b7ee915' AND unit = 'piece' AND status = 'active') IS DISTINCT FROM 40
       OR (SELECT category FROM public.portion_category_map WHERE food_item_id = '8cbd7524-bc18-5e4c-862b-cd6d61ee08b6') IS DISTINCT FROM 'liquid_dish' THEN
      RAISE EXCEPTION '054: dal / chai / roti spot checks failed';
    END IF;
  END IF;
  RAISE NOTICE '054 ok: % portion rows (% active), % categories, % words, % map rows, mode %',
    (SELECT count(*) FROM public.portion_units), (SELECT count(*) FROM public.portion_units WHERE status = 'active'),
    (SELECT count(*) FROM public.portion_categories), (SELECT count(*) FROM public.portion_category_words),
    (SELECT count(*) FROM public.portion_category_map), CASE WHEN v_go THEN 'production' ELSE 'replay' END;
END
$chk$;

NOTIFY pgrst, 'reload schema';
